INSERT INTO profession_details (profession_id, reality, pros, cons) VALUES
(31, 'Не "мастер на все руки". Это 80% рутинного ремонта, 15% "а почему так сломалось?", и 5% гордости от починенного двигателя.', '["Виден результат — починил", "Работа руками, не в офисе", "Востребовано всегда", "Можно свой бизнес"]', '["80% рутины", "Грязь, масло, запах", "Физический труд", "Зарплата на старте низкая"]'),
(32, 'Не "шеф из рекламы". Это 60% подготовки, 30% жары и давления, и 10% "клиент недоволен".', '["Творчество каждый день", "Виден результат — блюдо", "Можно работать в любой точке мира", "Свой ресторан — мечта"]', '["60% подготовки, не креатив", "Жара, давление, выгорание", "Ноги устают", "Вечер-ночь-выходные"]'),
(33, 'Не "свобода дорог". Это 90% монотонности, 5% пробок, и 5% "спасибо" от клиента.', '["Свобода графика (иногда)", "Видишь страну/город", "Нет начальника над душой", "Просто работа — не думаешь"]', '["90% монотонности", "Пробки, аварии, ГИБДД", "Сидячий образ — здоровье", "Зарплата потолок"]'),
(34, 'Не "магия тока". Это 70% кабелей в пыли, 20% документации, и 10% "фаза нулевая, а я живой".', '["Востребовано всегда", "Виден результат — свет есть", "Можно работать в любой сфере", "Свой бизнес — электрики"]', '["70% кабелей в пыли", "Опасность — ток убивает", "Физический труд", "Выгорание через 5 лет"]'),
(35, 'Не "пасторальная идиллия". Это грязь, комары, ранние подъёмы, зависимость от погоды и цен.', '["Работа на природе — не в офисе", "Виден результат — вырастил", "Можно свой бизнес", "Продукты питания — всегда нужны"]', '["Погода — босс, которого не уволишь", "Сезон — 7 дней в неделю", "Зарплата на старте низкая", "Грязь, комары, физический труд"]'),
(36, 'Не "мастер Икеи". Это 50% точных замеров, 40% пыли и стружки, и 10% "а вдруг криво?".', '["Виден результат — мебель", "Работа руками", "Творчество + техника", "Можно свой цех"]', '["50% замеров, не творчество", "Пыль, стружка, шум", "Физический труд", "Заказы нерегулярные"]'),
(37, 'Не "железный человек". Это 80% жары и искр, 15% точности, и 5% "шов идеален".', '["Высокая зарплата при опыте", "Востребовано везде", "Виден результат — построил", "Профессия на века"]', '["80% жары и искр", "Опасность — ожоги", "Физический труд", "Выгорание через 5 лет"]'),
