(39, 'Не "строитель мечты". Это 60% тяжести, 30% погоды, и 10% "фундамент готов".', '["Виден результат — дом стоит", "Востребовано всегда", "Можно свой бизнес", "Команда — братство"]', '["60% тяжести", "Погода, холод, жара", "Опасность — травмы", "Сезонность работы"]'),
(40, 'Не "магия воды". Это 70% труб в плесени, 20% звонков "текёт!", и 10% "наконец-то тишина".', '["Востребовано всегда", "Виден результат — течь устранена", "Можно работать самому", "Зарплата растёт с опытом"]', '["70% труб в плесени", "Клиенты звонят в панике", "Физический труд", "Выезды — непредсказуемо"]'),
(41, 'Не "мода и подиум". Это 80% одинаковых операций, 15% "еще чуть-чуть", и 5% "село идеально".', '["Виден результат — платье готово", "Творчество + техника", "Можно свой ателье", "Востребовано всегда"]', '["80% рутины", "Глаза устают", "Зарплата на старте низкая", "Сезонность заказов"]'),
(42, 'Не "шоу кондитеров". Это 50% замесов в 4 утра, 40% выпечки, и 10% "крем не взбился".', '["Аромат — каждый день", "Виден результат — съели", "Творчество + точность", "Можно свой магазин"]', '["4 утра — начало смены", "Жара, пар, давление", "Ноги устают", "Выходные — busiest days"]'),
(43, 'Не "мясной бутик". Это 70% холода и крови, 20% точности ножа, и 10% "клиент хочет филе".', '["Востребовано всегда", "Виден результат — порция", "Физическая форма", "Можно свой цех"]', '["70% холода и крови", "Ранние подъёмы", "Физический труд", "Запах не отмывается"]'),
(44, 'Не "рыбалка с пивом". Это 80% ожидания, 15% погоды, и 5% "улов!"', '["Связь с природой", "Свобода (иногда)", "Свежий воздух", "Можно свой бизнес"]', '["80% ожидания", "Погода — босс", "Доход нестабильный", "Физический труд"]'),
