(47, 'Не "пиратские приключения". Это 70% рутины, 20% шторма, и 10% "порт впереди".', '["Видишь мир", "Команда — братство", "Свобода (иногда)", "Зарплата без налогов"]', '["70% рутины", "Шторм — страх", "Долгие отлучки от семьи", "Опасность — утопление"]'),
(48, 'Не "герой боевика". Это 60% бумаг, 30% патрулей, и 10% "преступление в секторе".', '["Служишь стране", "Стабильность", "Льготы, пенсия", "Команда — братство"]', '["60% бумаг", "Опасность — жизнь", "Дежурства, ночи", "Бюрократия давит"]'),
(49, 'Не "пожарный Сэм". Это 80% тренировок и проверок, 15% ложных вызовов, и 5% "огонь, вперёд!".', '["Спасаешь жизни — смысл", "Уважение в обществе", "Команда — братство", "Адреналин — редко, но мощно"]', '["80% рутины", "Огонь — реальная опасность", "Дежурства 24/7", "Травмы, выгорание"]'),
(50, 'Не "герой фильма". Это 90% ожидания "а вдруг?", 9% обезвреживания, и 1% "взрыв".', '["Спасаешь жизни — смысл", "Высокий статус", "Хладнокровие — навык на всю жизнь", "Зарплата достойная"]', '["90% ожидания", "Один неверный шаг — смерть", "ПТСР — норма", "Нельзя рассказать — секретно"]'),
(51, 'Не "картограф Google". Это 70% полевых работ, 20% обработки, и 10% "точность — метр".', '["Работа на природе", "Точность — гордость", "Востребовано в стройке", "Можно свой бизнес"]', '["70% поля, не офис", "Погода — босс", "Москиты, клещи", "Зарплата на старте низкая"]'),
(52, 'Не "водитель GTA". Это 80% внимания, 15% вибрации, и 5% "поднял 20 тонн".', '["Виден результат — построил", "Высокая зарплата при опыте", "Востребовано в стройке", "Можно работать везде"]', '["80% внимания — устаёшь", "Вибрация — здоровье", "Опасность — аварии", "Выгорание через 5 лет"]');
